WITH remaining_keys AS (SELECT id FROM inventory INTERSECT SELECT id FROM inventory WHERE quantity BETWEEN 145 AND 148), verified AS (SELECT s.* FROM inventory s JOIN remaining_keys k ON s.id = k.id) SELECT product_id, STDDEV_SAMP(quantity) AS quantity_stddev, COUNT(DISTINCT store_id) AS distinct_store_ids, SUM(quantity) AS total_quantity, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95, BIT_AND(quantity) AS quantity_bit_and FROM verified GROUP BY product_id;
